//! The two generated files: the scheme JSON (one class per line, so a
//! rebuild diffs line by line) and SOURCES.md.

use std::fmt::Write;

use shelfmark_core::scheme::SchemeDoc;

use crate::build::Stats;
use crate::sources::{Lock, Role};

/// The scheme as JSON: header fields pretty-printed, then one class per
/// line.
pub fn scheme_json(doc: &SchemeDoc) -> Result<String, String> {
    let err = |e: serde_json::Error| e.to_string();
    let mut head = doc.clone();
    head.classes.clear();
    let head = serde_json::to_string_pretty(&head).map_err(err)?;
    let head = head
        .trim_end()
        .strip_suffix('}')
        .and_then(|h| h.trim_end().strip_suffix("\"classes\": []"))
        .ok_or("unexpected scheme JSON layout")?;
    let mut out = format!("{head}\"classes\": [\n");
    for (i, c) in doc.classes.iter().enumerate() {
        let sep = if i + 1 < doc.classes.len() { "," } else { "" };
        let _ = writeln!(out, "    {}{sep}", serde_json::to_string(c).map_err(err)?);
    }
    out.push_str("  ]\n}\n");
    Ok(out)
}

/// SOURCES.md: what each source is, its lock entry, the license note and
/// what the build kept and dropped.
pub fn sources_md(lock: &Lock, s: &Stats, doc: &SchemeDoc) -> String {
    let mut o = String::new();
    let vocab: usize = doc.classes.iter().map(|c| c.vocab.len()).sum();
    let _ = write!(
        o,
        "# LCC outline scheme: sources\n\n\
         Generated by `src/shelfmark/tools/lcc-outline` (`lcc-outline build`); do not edit by hand.\n\
         `lcc.json` is scheme `{name}@{version}` with {n} classes and validates against\n\
         `src/shelfmark/schemas/scheme.schema.json` and `shelfmark_core::scheme::SchemeDoc`.\n\n\
         ## Rebuild\n\n\
         ```sh\n\
         cd src/shelfmark/tools/lcc-outline\n\
         cargo run --release -- fetch --cache /tmp/lcc-sources   # network; rewrites sources.lock.json\n\
         cargo run --release -- build --cache /tmp/lcc-sources   # offline; deterministic from the lock\n\
         cargo run --release -- check --cache /tmp/lcc-sources   # fails if lcc.json or SOURCES.md is stale\n\
         ```\n\n\
         `build` refuses any cached file whose sha256 differs from `sources.lock.json`.\n\n\
         ## License\n\n\
         All inputs are published by the Library of Congress. As works of the US government they are\n\
         not subject to copyright in the United States (17 U.S.C. 105). LC asks that the source be\n\
         credited: Library of Congress Classification and Library of Congress Subject Headings,\n\
         Library of Congress, Policy, Training, and Cooperative Programs Division. The derived\n\
         `lcc.json` keeps the outline captions verbatim.\n\n\
         ## Sources\n\n",
        name = doc.name,
        version = doc.version,
        n = doc.classes.len(),
    );
    let roles = [
        (
            Role::ClassOutline,
            "LC Classification Outline: the 21 main classes and subclass captions",
        ),
        (
            Role::Outline,
            "FreeLCC 2024 outline PDFs: numbered spans, captions and scope notes",
        ),
        (
            Role::Lcsh,
            "LCSH bulk MADS/RDF (N-Triples): headings and their LCC numbers",
        ),
        (
            Role::IdRecord,
            "id.loc.gov classification records: captions for numbers printed without one",
        ),
    ];
    for (role, what) in roles {
        let _ = writeln!(
            o,
            "### {what}\n\n| file | fetched | bytes | sha256 |\n|---|---|---|---|"
        );
        for l in lock.sources.iter().filter(|l| l.role == role) {
            let _ = writeln!(
                o,
                "| [{}]({}) | {} | {} | `{}` |",
                l.file, l.url, l.fetched, l.bytes, l.sha256
            );
        }
        o.push('\n');
    }
    let _ = write!(
        o,
        "## What the build kept\n\n\
         - main classes: {classes}\n\
         - subclasses: {subs}\n\
         - numbered spans and numbers: {spans}\n\
         - numbers whose PDF page printed captions apart from numbers, captioned from their id.loc.gov record: {recs}\n\
         - outline lines whose code repeated an earlier class (caption kept as an `lcc` vocabulary term): {merged}\n\
         - LCSH links: {links} on {with} classes (from {heads} headings whose LCC number is exactly a class code or span)\n\
         - vocabulary links in all: {vocab}\n\n\
         ## What the build dropped\n\n\
         - spans wholly in parens (no longer used): {obsolete}\n\
         - K form-division table lines (table numbers, not class numbers): {tables}\n\
         - lines without a number that continued nothing (section headings between blank lines): {unparsed}\n\
         - numbers with no caption in the PDF and no id.loc.gov record: {uncap}\n\
         - lines that start like a number but do not parse: {bad}\n\
         - codes outside the code grammar: {off}\n\
         - letter prefixes with no caption in either outline (their spans nest under the main class): {unlab}\n",
        classes = s.classes,
        subs = s.subclasses,
        spans = s.spans,
        merged = s.merged,
        recs = s.from_records,
        links = s.lcsh_links,
        with = s.classes_with_lcsh,
        heads = s.lcsh_headings,
        vocab = vocab,
        obsolete = s.obsolete,
        tables = s.table_lines,
        unparsed = s.unparsed,
        uncap = list(&s.uncaptioned),
        bad = list(&s.bad_numbers),
        off = list(&s.off_grammar),
        unlab = list(&s.unlabelled_prefixes),
    );
    o
}

fn list(items: &[String]) -> String {
    if items.is_empty() {
        "none".to_string()
    } else {
        format!("{} ({})", items.len(), items.join(", "))
    }
}
